// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;

    function setUp() public {
        c = new MY_BANK(address(new Log()));
    }

    function testFuzz_property(uint256 unlockTime, uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        // Admissible domain: an actor that is not the test contract itself and not the C contract,
        // a nonzero deposit of at least MinSum, and an unlock time in the future relative to now.
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(unlockTime > block.timestamp);
        vm.assume(unlockTime <= type(uint256).max - 1);
        vm.assume(amount >= c.MinSum());

        // Fund the actor and deposit exactly at the stored unlockTime boundary.
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        ( , uint256 balanceBefore) = c.Acc(actor);
        require(balanceBefore == amount, "setup deposit did not register");

        // Warp to EXACTLY the stored unlockTime. The reference's strict `>` check must block collection;
        // the mutant's `>=` check allows collection here.
        vm.warp(unlockTime);

        uint256 collectorBalanceBefore = actor.balance;
        vm.prank(actor);
        c.Collect(amount);

        ( , uint256 balanceAfter) = c.Acc(actor);
        bool balanceUnchanged = (balanceAfter == balanceBefore);
        bool noEtherMoved = (actor.balance == collectorBalanceBefore);

        // General rule: at block.timestamp == acc.unlockTime, a Collect call must not change the
        // holder's recorded balance nor move Ether to the holder.
        assertTrue(balanceUnchanged && noEtherMoved, "Collect must not settle at exactly unlockTime");
    }
}
